import * as THREE from './assets/three.module.js';
import {getPosition,getTimes} from './assets/suncalc.js';
import {cityInfo,periods,periodAt,artUrl} from './catalog.js';
import {parts,offset,previewInstant,pad} from './time-utils.js';
import {Illustration} from './illustration.js';
import {makeCity3D} from './scene3d.js';
import {installImmersive} from './immersive.js';
import {installMusic} from './music.js';
import {installCityPicker} from './city-picker.js';
import {initialSelection,selectionURL} from './selection.js';
const $=id=>document.getElementById(id),sides=['left','right'],reduceMotion=matchMedia('(prefers-reduced-motion: reduce)');
let saved={};try{saved=JSON.parse(localStorage.getItem('quiet-hours.v3'))||{};}catch{}
const selected=initialSelection(location.search,saved.cities),panelCities={},models={},art={},activePeriods={},modes={left:'art',right:'art'};
for(const side of sides){panelCities[side]=cityInfo(selected[side]);if(['art','3d','live'].includes(saved.modes?.[side]))modes[side]=saved.modes[side];}
let motion=!reduceMotion.matches,preview=null,previewSide='right',touring=false,tourStart=0,tourMinute=0,lastFrame=0,lastTourMinute=-1;
const current=()=>preview===null?new Date():new Date(preview);
function persist(){try{localStorage.setItem('quiet-hours.v3',JSON.stringify({cities:selected,modes}));history.replaceState(null,'',selectionURL(location.href,selected));}catch{}}
function card(side){return `<article class="city-card" id="${side}-card"><div class="scene" id="${side}-scene"><canvas class="model-canvas" id="${side}-canvas"></canvas><div class="illustration-layer" id="${side}-illustration"><div class="generic-scene" hidden><div class="generic-hills"></div><div class="generic-houses"></div><div class="generic-water"></div><span>通用光景 · 專屬插畫待製作</span></div><canvas class="art-canvas" id="${side}-art-canvas"></canvas><div class="cloud cloud-a"></div><div class="cloud cloud-b"></div><img class="moving-foliage" alt="" aria-hidden="true"></div><div class="scene-error" id="${side}-art-error" hidden><p>這幅插畫暫時未能載入</p><button class="quiet-button" data-retry="${side}">重新載入 ↻</button></div><div class="scene-error" id="${side}-fallback" hidden><p>此裝置無法顯示 3D</p><span>請切換 2D 插畫繼續觀看。</span></div><div class="scene-vignette"></div><div class="scene-top"><span class="scene-kind" id="${side}-kind"></span><span class="sun-label" id="${side}-light"></span></div><div class="scene-caption"><span id="${side}-tagline"></span><p id="${side}-caption"></p></div><span class="period-caption" id="${side}-period"></span><div class="live-panel" id="${side}-live" hidden></div></div><div class="city-details"><div class="place-line"><div class="place-name"><div class="mini-clock" aria-hidden="true"><i class="hand hour-hand" id="${side}-hour-hand"></i><i class="hand minute-hand" id="${side}-minute-hand"></i></div><div><span class="country" id="${side}-country"></span><h2><button class="city-choose" data-choose="${side}" id="${side}-choose"></button></h2></div></div><div class="mode-switch"><button data-side="${side}" data-mode="live">Live View ↗</button><button data-side="${side}" data-mode="art">2D 插畫</button><button data-side="${side}" data-mode="3d">3D 動畫</button></div></div><div class="time-line"><time id="${side}-time">--:--</time><span class="seconds" id="${side}-seconds">--</span><span class="zone" id="${side}-zone"></span></div><div class="city-meta"><span id="${side}-date"></span><span id="${side}-solar"></span></div><p class="mode-note" id="${side}-note"></p></div></article>`;}
$('worlds').innerHTML=card('left')+'<div class="between"><span class="between-line"></span><span id="difference"></span><button id="swap" aria-label="交換兩地位置">⇄</button><span class="between-line"></span></div>'+card('right');
const picker=installCityPicker(chooseCity,current),immersiveClocks=installImmersive(panelCities,side=>picker.open(side));installMusic();
function solarState(date,c){const sun=getPosition(date,c.lat,c.lon);return {sun,day:THREE.MathUtils.smoothstep(sun.altitude,-7,9),gold:1-THREE.MathUtils.smoothstep(Math.abs(sun.altitude-2),0,20),label:sun.altitude>8?'日光':sun.altitude>0?'金色時刻':sun.altitude>-7?'暮光':'夜色'};}
function solarTime(value,zone){return value instanceof Date&&!isNaN(value)?new Intl.DateTimeFormat('en-GB',{timeZone:zone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(value):'—';}
function updateTime(){const date=current();for(const side of sides){const c=panelCities[side],p=parts(date,c.zone),period=periodAt(p.hour),sun=solarState(date,c),times=getTimes(previewInstant(720,c.zone,date),c.lat,c.lon);immersiveClocks.update(side,p);const layer=$(side+'-illustration');layer.style.setProperty('--leaf-brightness',.4+sun.day*.6);layer.style.setProperty('--cloud-opacity',.13+sun.day*.19);layer.style.setProperty('--generic-day',sun.day);layer.style.setProperty('--generic-sky',sun.day>.5?'#b9cdd2':sun.day>.1?'#b6a5b1':'#29374e');$(side+'-time').textContent=`${pad(p.hour)}:${pad(p.minute)}`;$(side+'-time').dateTime=date.toISOString();$(side+'-seconds').textContent=pad(p.second);$(side+'-date').textContent=new Intl.DateTimeFormat('zh-TW',{timeZone:c.zone,month:'long',day:'numeric',weekday:'short'}).format(date);$(side+'-solar').textContent=`↑ ${solarTime(times.sunrise,c.zone)}　↓ ${solarTime(times.sunset,c.zone)}`;$(side+'-hour-hand').style.transform=`rotate(${p.hour*30+p.minute*.5}deg)`;$(side+'-minute-hand').style.transform=`rotate(${p.minute*6}deg)`;$(side+'-period').textContent=modes[side]==='live'?'':`${period.icon} ${period.name}`;$(side+'-light').textContent=modes[side]==='art'?`${period.icon} ${period.name}`:`☼ ${sun.label}`;
 const key=selected[side]+'-'+period.key;if(activePeriods[side]!==key){activePeriods[side]=key;const url=artUrl(selected[side],period);if(url)art[side]?.load(url,motion);$(side+'-art-canvas').setAttribute('aria-label',`${c.name} ${period.name}動態插畫`);}if(modes[side]==='3d')models[side]?.light(date,sun);}
const difference=(offset(date,panelCities.right.zone)-offset(date,panelCities.left.zone))/60;$('difference').textContent=`${difference>=0?'+':''}${Number(difference.toFixed(2))}h`;const p=parts(date,panelCities[previewSide].zone);$('preview-time').textContent=`${pad(p.hour)}:${pad(p.minute)}`;$('time-slider').value=p.hour*60+p.minute;$('preview-status').textContent=preview===null?'跟隨當下 · 兩地同步':touring?'一天光影漫遊 · 加速預覽':'時間預覽中 · 兩地同步';document.querySelectorAll('[data-period]').forEach(b=>{const on=b.dataset.period===periodAt(p.hour).key;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});}
function setMode(side,mode,save=true){modes[side]=mode;const c=panelCities[side];$(side+'-live').hidden=mode!=='live';$(side+'-illustration').hidden=mode!=='art';$(side+'-canvas').hidden=mode!=='3d';$(side+'-kind').textContent=mode==='art'?(c.artPrefix?'2D / 分時段插畫':'2D / 通用光景'):mode==='3d'?'3D / 立體光景':'LIVE / 真實城市';$(side+'-note').textContent=mode==='art'?(c.artPrefix?(c.dry?'八幅時段插畫 · 樹影與雲層慢慢流動':'八幅時段插畫 · 水面局部循環'):'通用光景 · 此城市的專屬插畫尚待製作'):mode==='3d'?(c.artPrefix?'地標日照隨當地時間變化 · 非即時天氣':'通用城市模型 · 日照依當地座標計算'):'公開來源外連觀看，實際可用性依來源網站為準。';document.querySelectorAll(`[data-side="${side}"][data-mode]`).forEach(b=>{const on=b.dataset.mode===mode;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});art[side].visible=mode==='art'&&!!c.artPrefix;if(mode==='3d'&&!models[side]){try{models[side]=makeCity3D(selected[side],side);}catch(error){console.error(error);}}$(side+'-fallback').hidden=mode!=='3d'||!!models[side];models[side]?.setVisible(mode==='3d');$(side+'-art-error').hidden=mode!=='art'||!art[side].failed||!c.artPrefix;if(save)persist();updateTime();art[side].render(performance.now()/1000,motion);}
function refreshCity(side){const c=panelCities[side];$(side+'-card').className='city-card '+selected[side];$(side+'-country').textContent=c.country;$(side+'-choose').innerHTML=`${c.name} <span>${c.english}</span> <small>⌄</small>`;$(side+'-choose').setAttribute('aria-label',`更換${side==='left'?'左':'右'}側城市，目前${c.name}`);$(side+'-zone').textContent=c.zone.replace('/',' / ');$(side+'-caption').textContent=c.caption;$(side+'-tagline').textContent=c.tagline;$(side+'-canvas').setAttribute('aria-label',`${c.name} 3D 日照場景`);const layer=$(side+'-illustration');layer.querySelector('.generic-scene').hidden=!!c.artPrefix;$(side+'-art-canvas').hidden=!c.artPrefix;const foliage=layer.querySelector('.moving-foliage'),leftFoliage=c.foliageSide==='left'||['taipei','munich','newyork'].includes(selected[side]);foliage.hidden=!c.artPrefix;foliage.src='assets/'+(c.foliageAsset||(leftFoliage?'taipei':'paris')+'-foliage.png');layer.classList.toggle('foliage-left',leftFoliage);layer.classList.toggle('foliage-right',!leftFoliage);$(side+'-live').innerHTML=c.live?`<span class="live-status">${c.live.availability==='offline'?'公開來源 · 最近回報離線':'公開影像 · 外連觀看'}</span><p class="eyebrow">A WINDOW TO THE REAL WORLD</p><h3>看看此刻的${c.name}</h3><p>${c.live.name}<br>${c.live.availability==='offline'?`上次查核（${c.live.checkedOn}）來源標示離線，可前往確認是否恢復。`:'前往來源網站觀看當地影像。'}</p><a href="${c.live.url}" target="_blank" rel="noopener noreferrer">開啟公開攝影機 ↗</a><small>來源地點可能與插畫取景不同；影像可用性與延遲依來源為準。</small>`:`<span class="live-status">尚未收錄公開來源</span><h3>${c.name}的真實窗景</h3><p>此城市尚未收錄已確認的公開攝影機。<br>可先使用插畫或 3D 光景。</p>`;art[side].city=selected[side];art[side].water={...c.water,motion:{...c.water.motion,phase:c.water.motion.phase+(side==='right'?1.17:0)}};activePeriods[side]=null;}
function chooseCity(side,id){if(selected[side]===id)return;stopTour();models[side]?.dispose();delete models[side];selected[side]=id;panelCities[side]=cityInfo(id);art[side].token++;art[side].url=null;art[side].failed=false;refreshCity(side);setMode(side,modes[side],false);refreshPreview();persist();}
function refreshPreview(){$('preview-city').innerHTML=sides.map(side=>`<option value="${side}">${side==='left'?'左':'右'} · ${panelCities[side].name}當地時間</option>`).join('');$('preview-city').value=previewSide;library();updateTime();}
function library(){const c=panelCities[previewSide];$('library-title').textContent=c.artPrefix?`${c.name}的一天，八種溫柔。`:`${c.name} · 通用光景`;if(!c.artPrefix){$('period-grid').innerHTML='<p class="generic-library-note">此城市可預覽時間與日照，專屬八時段插畫尚待製作。</p>';return;}$('period-grid').innerHTML=periods.map(p=>`<button class="period-tile" data-period="${p.key}" aria-label="預覽${c.name}${p.name}插畫" aria-pressed="false"><img src="${artUrl(selected[previewSide],p)}" alt="${c.name}${p.name}插畫縮圖" loading="lazy"><span class="tile-label">${p.name}<span>${p.icon}</span></span><small>${pad(p.start)}:00–${pad(p.end)}:00</small></button>`).join('');document.querySelectorAll('[data-period]').forEach(b=>b.addEventListener('click',()=>{stopTour();const p=periods.find(p=>p.key===b.dataset.period);preview=+previewInstant(p.start*60+30,panelCities[previewSide].zone);setMode(previewSide,'art');}));}
function stopTour(){touring=false;$('day-play').textContent='▷ 光影漫遊';$('day-play').setAttribute('aria-pressed','false');}
function applyMotion(){document.body.classList.toggle('still',!motion);$('motion').textContent=motion?'◌ 動態開啟':'◯ 靜態模式';$('motion').setAttribute('aria-pressed',String(motion));if(!motion)stopTour();updateTime();Object.values(art).forEach(a=>a.render(performance.now()/1000,motion));}
for(const side of sides){art[side]=new Illustration(selected[side],$(side+'-art-canvas'),panelCities[side].water);$(side+'-art-canvas').addEventListener('art-error',()=>{$(side+'-art-error').hidden=modes[side]!=='art';});refreshCity(side);setMode(side,modes[side],false);}
document.querySelectorAll('[data-choose]').forEach(b=>b.addEventListener('click',()=>picker.open(b.dataset.choose)));document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.side,b.dataset.mode)));document.querySelectorAll('[data-retry]').forEach(b=>b.addEventListener('click',()=>{const side=b.dataset.retry;art[side].url=null;activePeriods[side]=null;updateTime();$(side+'-art-error').hidden=true;}));
$('motion').addEventListener('click',()=>{motion=!motion;applyMotion();});reduceMotion.addEventListener('change',()=>{motion=!reduceMotion.matches;applyMotion();});$('time-slider').addEventListener('input',e=>{stopTour();preview=+previewInstant(Number(e.target.value),panelCities[previewSide].zone);updateTime();});$('preview-city').addEventListener('change',e=>{stopTour();previewSide=e.target.value;library();updateTime();});$('reset').addEventListener('click',()=>{stopTour();preview=null;updateTime();});$('day-play').addEventListener('click',()=>{if(touring){stopTour();return;}motion=true;applyMotion();touring=true;tourMinute=Number($('time-slider').value);tourStart=performance.now();lastTourMinute=-1;$('day-play').textContent='Ⅱ 暫停漫遊';$('day-play').setAttribute('aria-pressed','true');});$('swap').addEventListener('click',()=>{const left=selected.left,right=selected.right,leftMode=modes.left,rightMode=modes.right;modes.left=rightMode;modes.right=leftMode;chooseCity('left',right);chooseCity('right',left);for(const side of sides)setMode(side,modes[side],false);persist();});
refreshPreview();applyMotion();setInterval(()=>{if(!touring&&!document.hidden)updateTime();},1000);
function frame(t){requestAnimationFrame(frame);if(document.hidden||t-lastFrame<1000/24)return;lastFrame=t;if(touring){const elapsed=(t-tourStart)/1000,minute=Math.floor((tourMinute+elapsed*24)%1440);if(minute!==lastTourMinute){lastTourMinute=minute;preview=+previewInstant(minute,panelCities[previewSide].zone);updateTime();}if(elapsed>=60)stopTour();}if(motion){for(const side of sides){if(modes[side]==='3d')models[side]?.animate(t/1000);if(modes[side]==='art')art[side].render(t/1000,true);}}}
requestAnimationFrame(frame);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopTour();else updateTime();});
